META = dict(nama="Recycling", jp="資源循環", emoji="♻️", co="リサイクル会社")
SPEC = dict(kerja="ごみを正しく分けて、資源として生かしている", kerja_id="memilah sampah dengan benar dan memanfaatkannya sebagai sumber daya", soal={
 "shibou-01": ("なぜリサイクルの仕事を選びましたか。", "Mengapa Anda memilih pekerjaan daur ulang?", "環境を守る仕事に、興味があります。ごみを、もう一度使えるものにする仕事がしたいです。", "Saya tertarik pada pekerjaan menjaga lingkungan. Saya ingin bekerja mengubah sampah menjadi sesuatu yang bisa dipakai lagi.", [("リサイクル", "daur ulang"), ("環境", "lingkungan"), ("資源", "sumber daya"), ("守る", "menjaga")]),
 "shibou-02": ("なぜ日本でリサイクルを学びたいですか。", "Mengapa Anda ingin belajar daur ulang di Jepang?", "日本は、ごみの分け方が細かくて、リサイクルの技術も進んでいると聞きました。その方法を学びたいです。", "Saya dengar di Jepang cara memilah sampah sangat rinci dan teknologi daur ulangnya maju. Saya ingin mempelajari caranya.", [("分別", "pemilahan"), ("技術", "teknologi"), ("学ぶ", "belajar")]),
 "shibou-04": ("この仕事に興味を持った理由は何ですか。", "Apa alasan Anda tertarik pada pekerjaan ini?", "ごみが、新しい製品の材料になることを知って、おもしろいと思いました。地球のために、役に立ちたいです。", "Saya merasa menarik setelah tahu sampah bisa menjadi bahan produk baru. Saya ingin berguna bagi bumi.", [("材料", "bahan"), ("地球", "bumi"), ("役に立つ", "berguna")]),
 "shibou-05": ("リサイクルの仕事で、一番楽しみなことは何ですか。", "Apa yang paling Anda nantikan dari pekerjaan daur ulang?", "分別の方法や、機械の使い方を覚えて、正しく仕事ができるようになることです。日本の環境の取り組みも学びたいです。", "Belajar cara memilah dan memakai mesin sehingga bisa bekerja dengan benar. Saya juga ingin belajar upaya lingkungan Jepang.", [("分別", "pemilahan"), ("機械", "mesin"), ("取り組み", "upaya")]),
 "shigoto-01": ("リサイクルの主な仕事は何だと思いますか。", "Menurut Anda, apa pekerjaan utama daur ulang?", "集まったごみや、使い終わったものを、種類ごとに分けて、資源として使えるようにする仕事だと思います。", "Saya kira pekerjaannya memilah sampah dan barang bekas menurut jenis sehingga bisa dimanfaatkan sebagai sumber daya.", [("分別", "pemilahan"), ("種類", "jenis"), ("資源", "sumber daya")]),
 "shigoto-02": ("朝早くから働くことはできますか。", "Apakah Anda bisa bekerja dari pagi buta?", "はい、できます。早く寝て、朝の準備をしっかりします。", "Ya, bisa. Saya tidur lebih awal dan bersiap dengan baik di pagi hari.", [("早起き", "bangun pagi"), ("準備", "persiapan"), ("体調", "kondisi badan")]),
 "shigoto-03": ("においや汚れがある環境でも、大丈夫ですか。", "Apakah Anda baik-baik saja di lingkungan yang berbau dan kotor?", "はい、大丈夫です。マスクや手袋をつけて、作業のあとで、手や体をきれいに洗います。", "Ya, tidak masalah. Saya memakai masker dan sarung tangan, lalu mencuci tangan dan badan hingga bersih setelah bekerja.", [("におい", "bau"), ("汚れ", "kotoran"), ("マスク", "masker")]),
 "shigoto-04": ("夏の暑い日や、冬の寒い日に、外や工場で働けますか。", "Bisakah Anda bekerja di luar atau di pabrik saat musim panas yang terik dan musim dingin?", "はい、大丈夫です。夏は、こまめに水を飲んで、冬は服をたくさん着ます。", "Ya, tidak masalah. Saat musim panas saya sering minum air dan saat dingin memakai banyak lapis pakaian.", [("暑い", "panas"), ("寒い", "dingin"), ("こまめに", "sering/rutin")]),
 "shigoto-05": ("重いものを持ったり、立って作業したりする体力はありますか。", "Apakah Anda punya stamina untuk mengangkat barang berat dan bekerja sambil berdiri?", "はい、あります。毎日運動をして、体力をつけています。重いものは、一人で持たないようにします。", "Ya, ada. Saya berolahraga setiap hari. Barang berat tidak saya angkat sendirian.", [("体力", "stamina"), ("重い", "berat"), ("運動", "olahraga")]),
 "shigoto-06": ("ごみが多い時期に、残業があっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan lembur saat sampah sedang banyak?", "はい、大丈夫です。忙しい時期は、チームでがんばります。体調にも気をつけます。", "Ya, tidak masalah. Saat sibuk kami berusaha bersama. Saya juga menjaga kondisi badan.", [("繁忙期", "musim sibuk"), ("残業", "lembur"), ("チーム", "tim")]),
 "shigoto-07": ("機械や、道具を使うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memakai mesin dan alat?", "使う前に、機械の状態を確認します。動いている部分には、手を入れません。使い方が分からないときは、使いません。", "Sebelum dipakai saya memeriksa kondisi mesin. Saya tidak memasukkan tangan ke bagian yang bergerak. Kalau tidak tahu cara pakainya, saya tidak memakainya.", [("機械", "mesin"), ("確認", "memastikan"), ("手を入れる", "memasukkan tangan")]),
 "shigoto-08": ("ごみの中の、危ないものに気づいたとき、どうしますか。", "Apa yang Anda lakukan kalau menemukan benda berbahaya di dalam sampah?", "さわらないで、すぐに責任者に知らせます。ガラスや、針などは、特に気をつけます。", "Saya tidak menyentuhnya dan segera memberi tahu penanggung jawab. Saya sangat berhati-hati pada pecahan kaca dan jarum.", [("危険物", "benda berbahaya"), ("ガラス", "kaca"), ("知らせる", "memberi tahu")]),
 "shigoto-09": ("リサイクルの仕事で、大切なことは何だと思いますか。", "Menurut Anda, apa yang penting dalam pekerjaan daur ulang?", "ごみを、正しく分けることだと思います。分け方を間違えると、リサイクルできなくなります。", "Menurut saya, memilah sampah dengan benar. Kalau salah memilah, barang itu tidak bisa didaur ulang.", [("分別", "pemilahan"), ("間違える", "keliru"), ("正しく", "dengan benar")]),
 "shigoto-10": ("ごみが届いてから、資源になるまで、どんな作業がありますか。", "Pekerjaan apa saja sejak sampah tiba sampai menjadi sumber daya?", "ごみを受け取って、種類ごとに分けます。機械で細かくしたり、洗ったりして、新しい材料にします。", "Sampah diterima dan dipilah menurut jenis. Lalu dicacah dengan mesin atau dicuci, dan diubah menjadi bahan baru.", [("破砕", "pencacahan"), ("選別", "pemilahan"), ("材料", "bahan")]),
 "shigoto-11": ("日本のごみの分け方を、知っていますか。", "Apakah Anda tahu cara memilah sampah di Jepang?", "燃えるごみ、燃えないごみ、プラスチック、びん、かんなどに分けると聞きました。これから、しっかり勉強します。", "Saya dengar sampah dipilah menjadi sampah terbakar, tidak terbakar, plastik, botol, kaleng, dan sebagainya. Saya akan belajar dengan sungguh-sungguh.", [("燃えるごみ", "sampah terbakar"), ("プラスチック", "plastik"), ("びん・かん", "botol dan kaleng")]),
 "shigoto-12": ("金属や、プラスチックなど、いろいろな種類を見分けることはできますか。", "Apakah Anda bisa membedakan berbagai jenis seperti logam dan plastik?", "まだ分からないものもありますが、勉強します。先輩に教えてもらって、少しずつ覚えます。", "Masih ada yang belum saya kenali, tetapi saya akan belajar. Saya diajari senior dan menghafal sedikit demi sedikit.", [("金属", "logam"), ("見分ける", "membedakan"), ("覚える", "menghafal")]),
 "shigoto-13": ("環境を守るために、あなたができることは何ですか。", "Apa yang bisa Anda lakukan untuk menjaga lingkungan?", "ごみを、決まりのとおりに分けることです。ものを大切に使って、むだなごみを減らします。", "Memilah sampah sesuai aturan. Saya memakai barang dengan hati-hati dan mengurangi sampah yang sia-sia.", [("減らす", "mengurangi"), ("むだ", "sia-sia"), ("大切にする", "menghargai")]),
 "taiou-02": ("ごみを、間違った所に分けてしまったら、どうしますか。", "Apa yang Anda lakukan kalau keliru memilah sampah ke tempat yang salah?", "すぐに正直に報告します。どうして間違えたか考えて、次は、分別表をよく確認します。", "Saya segera melapor jujur. Saya memikirkan penyebabnya dan lain kali memeriksa tabel pemilahan dengan teliti.", [("間違える", "keliru"), ("分別表", "tabel pemilahan"), ("報告", "melapor")]),
 "taiou-06": ("急に、ごみの量が増えたり、予定が変わったりしたら、どうしますか。", "Apa yang Anda lakukan kalau jumlah sampah mendadak bertambah atau rencana berubah?", "責任者の指示をよく聞いて、作業の順番を変えます。分からないときは、すぐに聞きます。", "Saya mendengarkan instruksi penanggung jawab dan mengubah urutan kerja. Kalau tidak paham, saya langsung bertanya.", [("急に", "mendadak"), ("量", "jumlah"), ("指示", "instruksi")]),
 "taiou-08": ("機械が急に止まったり、変な音がしたりしたら、どうしますか。", "Apa yang Anda lakukan kalau mesin mendadak berhenti atau berbunyi aneh?", "すぐに機械を止めて、責任者に知らせます。自分で直さないようにします。", "Saya segera menghentikan mesin dan memberi tahu penanggung jawab. Saya tidak memperbaikinya sendiri.", [("止まる", "berhenti"), ("変な音", "bunyi aneh"), ("知らせる", "memberi tahu")]),
 "taiou-11": ("忙しい時期で、疲れているとき、どう気持ちを保ちますか。", "Bagaimana Anda menjaga semangat saat sibuk dan lelah?", "忙しい時期は短いと理解しています。しっかり寝て、食事をとって、体調を保ちます。", "Saya paham musim sibuk itu singkat. Saya tidur cukup, makan baik, dan menjaga kondisi badan.", [("疲れる", "lelah"), ("体調", "kondisi badan"), ("睡眠", "tidur")]),
 "taiou-12": ("先輩の説明が早くて、分からないとき、どうしますか。", "Apa yang Anda lakukan kalau penjelasan senior terlalu cepat dan tidak Anda pahami?", "「すみません、もう一度ゆっくりお願いします」と言います。分からない言葉は、メモして、あとで聞きます。", "Saya bilang \"Maaf, tolong ulangi lebih pelan\". Kata yang tidak paham saya catat dan tanyakan nanti.", [("説明", "penjelasan"), ("ゆっくり", "pelan"), ("メモ", "catatan")]),
 "tim-01": ("ごみが多いとき、チームの人と、どのように作業を分けますか。", "Saat sampah banyak, bagaimana Anda membagi kerja dengan tim?", "責任者の指示で、受け取る人、分ける人、運ぶ人などに分かれます。早く終わったら、ほかの人を手伝います。", "Sesuai instruksi penanggung jawab, ada yang menerima, memilah, dan mengangkut. Kalau selesai lebih dulu, saya membantu yang lain.", [("分担", "pembagian tugas"), ("分ける", "memilah"), ("手伝う", "membantu")]),
 "tim-02": ("分け方が分からないものがあったとき、どうしますか。", "Apa yang Anda lakukan kalau ada barang yang tidak tahu cara memilahnya?", "勝手に判断しないで、すぐに先輩に聞きます。間違えたまま分けると、ほかの人が困るからです。", "Saya tidak memutuskan sendiri dan segera bertanya kepada senior. Karena salah memilah akan menyulitkan orang lain.", [("判断", "keputusan"), ("先輩", "senior"), ("確認", "memastikan")]),
 "tim-03": ("機械を使うとき、まわりの人と、どのようにコミュニケーションをとりますか。", "Bagaimana Anda berkomunikasi dengan orang sekitar saat memakai mesin?", "動かす前に、大きい声で「動かします」と言います。まわりの人が離れたか、必ず見ます。", "Sebelum menyalakan, saya berkata keras \"Saya nyalakan\". Saya selalu memeriksa apakah orang sekitar sudah menjauh.", [("声をかける", "memberi aba-aba"), ("離れる", "menjauh"), ("確認", "memastikan")]),
 "tim-04": ("職場の仲間と、どのように仲良くなりたいですか。", "Bagaimana Anda ingin akrab dengan rekan kerja?", "毎日、元気にあいさつをします。教えてもらったときは、「ありがとうございます」と言います。", "Setiap hari saya menyapa dengan semangat. Saat diajari, saya mengatakan \"Terima kasih\".", [("あいさつ", "salam"), ("仲間", "rekan"), ("仲良くなる", "menjadi akrab")]),
 "anzen-01": ("作業をするとき、必ず身につけるものは何ですか。", "Apa yang wajib dikenakan saat bekerja?", "ヘルメット、安全靴、手袋、マスクを必ず着けます。必要なときは、保護めがねも使います。", "Saya wajib memakai helm, sepatu keselamatan, sarung tangan, dan masker. Bila perlu saya juga memakai kacamata pelindung.", [("ヘルメット", "helm"), ("手袋", "sarung tangan"), ("保護めがね", "kacamata pelindung")]),
 "anzen-02": ("ごみの中の、ガラスや針などで、けがをしないために、何をしますか。", "Apa yang Anda lakukan agar tidak terluka oleh kaca dan jarum di dalam sampah?", "厚い手袋をつけて、手で直接さわりません。見つけたら、すぐに責任者に知らせます。", "Saya memakai sarung tangan tebal dan tidak menyentuhnya langsung dengan tangan. Kalau menemukannya, saya segera memberi tahu penanggung jawab.", [("厚い手袋", "sarung tangan tebal"), ("針", "jarum"), ("けが", "luka")]),
 "anzen-03": ("機械の近くで作業するとき、事故を防ぐために何をしますか。", "Apa yang Anda lakukan untuk mencegah kecelakaan saat bekerja dekat mesin?", "動いている機械には、手や服を近づけません。掃除や直すときは、必ず電源を切ります。", "Saya tidak mendekatkan tangan atau pakaian ke mesin yang bergerak. Saat membersihkan atau memperbaiki, saya selalu mematikan daya.", [("電源", "daya listrik"), ("巻き込まれる", "terjerat"), ("近づく", "mendekat")]),
 "anzen-04": ("もし、火事や、変なにおいがしたら、どうしますか。", "Apa yang Anda lakukan kalau ada api atau bau aneh?", "すぐに作業をやめて、大きい声で知らせます。責任者の指示で、決められた場所に避難します。", "Saya segera menghentikan pekerjaan dan memberi tahu dengan suara keras. Saya mengungsi ke tempat yang ditentukan sesuai instruksi penanggung jawab.", [("火事", "kebakaran"), ("避難", "mengungsi"), ("知らせる", "memberi tahu")]),
 "seikatsu-07": ("工場が多い地域での生活に、不便なことがあっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan ketidaknyamanan hidup di kawasan industri?", "大丈夫です。寮から会社までの行き方を、調べておきます。お店が遠いときは、まとめて買い物をします。", "Tidak masalah. Saya akan mengecek rute dari asrama ke perusahaan. Kalau toko jauh, saya belanja sekaligus.", [("寮", "asrama"), ("まとめて", "sekaligus"), ("調べる", "mengecek")]),
 "seikatsu-08": ("日本のリサイクルや、ごみの出し方について、知っていることはありますか。", "Apa yang Anda ketahui tentang daur ulang dan cara membuang sampah di Jepang?", "日本では、ごみの日が決まっていて、種類ごとに出すと聞きました。みんなが決まりを守る国だと思います。", "Saya dengar di Jepang hari pembuangan sampah ditentukan dan sampah dibuang menurut jenis. Menurut saya ini negara yang warganya mematuhi aturan.", [("ごみの日", "hari pembuangan sampah"), ("決まり", "aturan"), ("守る", "mematuhi")]),
 "mokuhyou-05": ("日本でリサイクルを学んだあと、自分の国でどんなことをしたいですか。", "Setelah belajar daur ulang di Jepang, apa yang ingin Anda lakukan di negara sendiri?", "日本で学んだ分別の方法や、環境を守る考え方を使って、自分の国の町を、きれいにしたいです。", "Saya ingin membuat kota di negara saya lebih bersih dengan memakai cara memilah dan cara berpikir menjaga lingkungan yang saya pelajari di Jepang.", [("分別", "pemilahan"), ("環境", "lingkungan"), ("きれいにする", "membersihkan")]),
})
